<?php require_once 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=strtolower(trim($_POST['email']));$pw=$_POST['password'];if(strlen($pw)<6)$err='Password must be at least 6 characters.';else{try{$st=$pdo->prepare("INSERT INTO users(name,email,password) VALUES(?,?,?)");$st->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'user'];go('index.php');}catch(Throwable $e){$err='Email already registered.';}}}$title='Register';include 'header.php';?><div class="row justify-content-center"><div class="col-md-6 panel"><h1>Create account</h1><?php if($err)echo '<div class="alert alert-danger">'.h($err).'</div>';?><form method="post"><input class="form-control mb-3" name="name" placeholder="Full name" required><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" type="password" name="password" placeholder="Password (min 6)" required><button class="btn btn-rose">Register</button></form></div></div><?php include 'footer.php'; ?>
